//! 🧪️ Actual post custody, allocator receipts and concurrent final-graph laws use the selected central retained applier.
use super::super::*;
use semio_framework_value::{retained_clone::RetainedCloneSource,retirement::RetireOwned};
#[path="../../../../../../../../../../../../../../🧰️framework/🔨️modules/🌱️value/📽️projection/👁️post/🧪️testing/🦀️.rs"]mod post_fixture;
#[path="../../../../../../../../../../../../../../🧰️framework/🔨️modules/🌱️value/🧪️testing/💾️allocator/🦀️.rs"]mod allocation;
use post_fixture::PostFixture;
use allocation::observe_retirement_allocations as observe;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn full()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<28,maximum_capacity_bytes:1<<28,maximum_release_bytes:1<<28,maximum_depth:4096}}
fn decode<T:semio_framework_value::FromValue>(v:&serde_json::Value)->T{semio_framework_pack_json::from_json_str(&v.to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{RetainedCloneSource::admit_owned(value,(),full()).map_err(|(e,_,_)|e).unwrap().0}
fn source_close<T:RetireOwned+Sync+'static>(source:&mut RetainedCloneSource<T>){for _ in 0..1000000{if source.terminal_is_empty(){return}let d=RetirementDemand{copy_bytes:source.next_close_copy_byte_demand().unwrap(),capacity_bytes:source.next_close_capacity_byte_demand(65536).unwrap(),release_bytes:source.next_close_release_byte_demand().unwrap(),depth:source.next_close_depth_demand().unwrap()};source.close_step(grant(d)).unwrap();}panic!("final graph original source close stalled")}
fn edited(mut value:serde_json::Value,patch:&serde_json::Value)->serde_json::Value{for op in patch.as_array().unwrap(){let(path,key)=op["path"].as_str().unwrap().rsplit_once('/').unwrap();let parent=value.pointer_mut(path).unwrap();match op["op"].as_str().unwrap(){"replace"=>{if let Some(rows)=parent.as_array_mut(){rows[key.parse::<usize>().unwrap()]=op["value"].clone()}else{parent.as_object_mut().unwrap().insert(key.to_owned(),op["value"].clone());}},"add"=>{if let Some(rows)=parent.as_array_mut(){let at=if key=="-"{rows.len()}else{key.parse().unwrap()};rows.insert(at,op["value"].clone())}else{parent.as_object_mut().unwrap().insert(key.to_owned(),op["value"].clone());}},"remove"=>{if let Some(rows)=parent.as_array_mut(){rows.remove(key.parse().unwrap());}else{parent.as_object_mut().unwrap().remove(key);}},_=>panic!("neutral witness operation")}}value}
fn close(owner:&mut protocol::RetainedDiffOwner<LayoutSnapshot,LayoutDiff>)->(usize,usize){owner.begin_close();let(mut born,mut freed)=(0,0);for _ in 0..1000000{if owner.terminal_is_empty(){return(born,freed)}let(d,heap)=observe(||owner.close_demand(65536).unwrap());assert_eq!(heap,(0,0));let(step,heap)=observe(||owner.close_step(Default::default()).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));let g=grant(d);let(step,heap)=observe(||owner.close_step(g).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;freed+=heap.1;}panic!("central final graph original close stalled")}
#[test]
fn central_original_final_graph_refuses_concurrent_invalid_graphs_and_matches_neutral_witnesses(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();let neutral:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/✅️validation/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){let before=edited(neutral["base"].clone(),&case["before"]);let live=edited(before.clone(),&case["live"]);let expected=edited(live.clone(),&case["final"]);let original:LayoutSnapshot=decode(&before);let held:LayoutSnapshot=decode(&live);let final_snapshot:LayoutSnapshot=decode(&expected);assert!(semio_s_artifact_layout_layout_model::validation::validate_document(&original).is_ok());assert!(semio_s_artifact_layout_layout_model::validation::validate_document(&held).is_ok());assert_eq!(semio_s_artifact_layout_layout_model::validation::validate_document(&final_snapshot).is_ok(),case["valid"].as_bool().unwrap());let event:LayoutDiff=decode(&case["diff"]);let mut baseline=source(original);let mut authored=source(event);let mut post=PostFixture::new(held);let text=post.stories[0].content.as_ptr();let(birth,heap)=observe(||protocol::begin_retained_diff::<LayoutSnapshot,LayoutDiff>(grant(protocol::retained_diff_birth_demand::<LayoutSnapshot,LayoutDiff>())).unwrap());let(mut owner,p)=birth;assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let(mut born,mut freed)=heap;let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);let mut done=false;for _ in 0..1000000{let(d,heap)=observe(||owner.preflight_demand(authored.borrow(),baseline.borrow(),post.borrow(),65536).unwrap());assert_eq!(heap,(0,0));let g=grant(d);for (axis,denied) in [RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:0,..g},RetainedCloneGrant{maximum_depth:0,..g},RetainedCloneGrant{maximum_capacity_bytes:0,..g},RetainedCloneGrant{maximum_release_bytes:0,..g}].into_iter().enumerate(){if(axis==3&&d.capacity_bytes==0)||(axis==4&&d.release_bytes==0){continue}let(step,heap)=observe(||protocol::preflight_retained_diff(&mut owner,authored.borrow(),baseline.borrow(),post.borrow(),65536,denied,&mut receiving).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}let(step,heap)=observe(||protocol::preflight_retained_diff(&mut owner,authored.borrow(),baseline.borrow(),post.borrow(),65536,g,&mut receiving).unwrap());let p=step.progress();assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;freed+=heap.1;if matches!(step,protocol::RetainedDiffPreflightStep::Admitted(..)|protocol::RetainedDiffPreflightStep::Refused(..)){assert_eq!(matches!(step,protocol::RetainedDiffPreflightStep::Admitted(..)),case["valid"].as_bool().unwrap(),"{}",case["name"]);done=true;break}}assert!(done);assert_eq!(post.stories[0].content.as_ptr(),text);post.mutable_read();assert_eq!(*post,decode::<LayoutSnapshot>(&live));let(b,f)=close(&mut owner);born+=b;freed+=f;assert_eq!(born,freed,"{}",case["name"]);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,0));drop(post);source_close(&mut authored);source_close(&mut baseline)}}
#[test]
fn central_actual_live_source_cancellation_cannot_restore_mutable_post_before_alias_closure(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧪️.json")).unwrap();let neutral:serde_json::Value=serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/✅️validation/🔣️.json")).unwrap();for case in corpus["cases"].as_array().unwrap(){for cut in corpus["cancelCuts"].as_array().unwrap(){let before=edited(neutral["base"].clone(),&case["before"]);let live=edited(before.clone(),&case["live"]);let mut baseline=source(decode::<LayoutSnapshot>(&before));let mut authored=source(decode::<LayoutDiff>(&case["diff"]));let mut post=PostFixture::new(decode::<LayoutSnapshot>(&live));let address=post.pages[0].id.as_ptr();let(mut owner,p)=protocol::begin_retained_diff::<LayoutSnapshot,LayoutDiff>(grant(protocol::retained_diff_birth_demand::<LayoutSnapshot,LayoutDiff>())).unwrap();let(mut born,mut freed)=(p.retained_capacity_bytes,p.released_bytes);let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);for _ in 0..cut.as_u64().unwrap(){let d=owner.preflight_demand(authored.borrow(),baseline.borrow(),post.borrow(),65536).unwrap();let(step,heap)=observe(||protocol::preflight_retained_diff(&mut owner,authored.borrow(),baseline.borrow(),post.borrow(),65536,grant(d),&mut receiving).unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));born+=heap.0;freed+=heap.1;if matches!(step,protocol::RetainedDiffPreflightStep::Admitted(..)|protocol::RetainedDiffPreflightStep::Refused(..)){break}}if cut.as_u64().unwrap()>0{assert!(owner.preflight_demand(authored.borrow(),baseline.borrow(),post.borrow().project(1,|v|v),65536).is_err());assert!(owner.preflight_demand(authored.borrow().project(1,|v|v),baseline.borrow(),post.borrow(),65536).is_err());let swapped=PostFixture::new(decode::<LayoutSnapshot>(&live));assert!(owner.preflight_demand(authored.borrow(),baseline.borrow(),swapped.borrow(),65536).is_err());drop(swapped)}let(b,f)=close(&mut owner);assert_eq!(born+b,freed+f);assert_eq!(post.pages[0].id.as_ptr(),address);post.mutable_read();assert_eq!(*post,decode::<LayoutSnapshot>(&live));drop(post);source_close(&mut authored);source_close(&mut baseline)}}}
